SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.admission_type, COUNT(DISTINCT pr.procedure_id) AS num_procedures, AVG(pr.duration) AS avg_duration, MIN(pr.duration) AS min_duration, MAX(pr.duration) AS max_duration FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN procedures_icd pr ON a.subject_id = pr.subject_id AND a.hadm_id = pr.hadm_id WHERE p.subject_id = 123456 AND p.gender = 'M' AND p.anchor_age = 95 AND p.anchor_year = 2020 AND p.anchor_year_group = '90-100' AND a.admission_type = 'TIA' AND pr.icd_code = '757071' AND (a.dischtime - a.admittime) BETWEEN 1 AND 3 THEN '1-3 day' WHEN (a.dischtime - a.admittime) BETWEEN 4 AND 7 THEN '4-7 day' ELSE 'Other' END AS admission_duration FROM procedures_icd pr JOIN admissions a ON pr.subject_id = a.subject_id AND pr.hadm_id = a.hadm_id JOIN patients p ON p.subject_id = a.subject_id WHERE p.subject_id = 123456 AND p.gender = 'M' AND p.anchor_age = 95 AND p.anchor_year = 2020 AND p.anchor_year_group = '90-100' AND a.admission_type = 'TIA' AND pr.icd_code = '757071' GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.admission_type, admission_duration;